        addChoice(choices,"Type",this::chooseKind);addChoice(choices,"Data",()->startActivity(new Intent(this,MetadataActivity.class)));addChoice(choices,"Year",this::chooseYear);addChoice(choices,"Reset filters",()->{kind="";year="";gallery();});addChoice(choices,"Export files",this::organizedExport);addChoice(choices,"Slideshow",()->{if(!items.isEmpty()){slideshow=true;immersive=true;open(0);scheduleSlide();}else message("No media yet","Import an export containing local images to start a slideshow.");});
        filters.addView(choices);content.addView(filters);gap(content,10);
        emptyGallery=new LinearLayout(this);emptyGallery.setOrientation(LinearLayout.VERTICAL);emptyGallery.setGravity(Gravity.CENTER);emptyGallery.setPadding(dp(16),dp(32),dp(16),dp(20));emptyGallery.setVisibility(View.GONE);emptyLabel=text("",16,MUTED);emptyLabel.setGravity(Gravity.CENTER);emptyGallery.addView(emptyLabel);gap(emptyGallery,16);browseAll=button("Browse all imported media",()->{chat="";chatTitle="";kind="";year="";gallery();});emptyGallery.addView(browseAll);content.addView(emptyGallery);
        grid=new GridView(this);grid.setNumColumns(GridView.AUTO_FIT);grid.setColumnWidth(dp(145));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setHorizontalSpacing(dp(10));grid.setVerticalSpacing(dp(10));
